  const iconChart = await iconToBase64Png(FaChartLine, "#FFFFFF", 256);
  const iconCode = await iconToBase64Png(FaCode, "#FFFFFF", 256);
  const iconUsers = await iconToBase64Png(FaUsers, "#FFFFFF", 256);
  const iconBulb = await iconToBase64Png(FaLightbulb, "#FFFFFF", 256);
  const iconArrow = await iconToBase64Png(FaArrowRight, `#${C.accentOrange}`, 256);
