  accentGold: "F5C342",
  white: "FFFFFF",
  offWhite: "F4F6F9",
  lightGray: "E2E8F0",
  midGray: "8896A6",
  darkText: "1B2A41",
  bodyText: "334155",
  subtleText: "64748B",
};

// Helpers
const shadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10 });

