    slide.addImage({ data: iconArrow, x: 3.4, y: 4.0, w: 0.3, h: 0.3 });

    slide.addText([
      { text: "64.8%", options: { fontSize: 28, fontFace: "Georgia", bold: true, color: C.accentOrange } },
      { text: "  2024", options: { fontSize: 12, fontFace: "Calibri", color: C.subtleText } },
