"left\", valign: \"middle\", margin: 0,\n    });\n\n    // Influence by role cards\n    const roles = [\n      { role: \"Sr. Executives\", pct: \"99%\", c: C.navy },\n      { role: \"Eng. Managers\", pct: \"87%\", c: C.teal },\n      { role: \"Product Mgrs\", pct: \"77%\", c: C.accentOrange },\n    ];\n    roles.forEach((r, i) => {\n      const y = 3.15 + i * 0.55;\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 5.3, y, w: 4.2, h: 0.45,\n        fill: { color: C.white },\n        shadow: shadow(),\n      });\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 5.3, y, w: 0.07, h: 0.45,\n        fill: { color: r.c },\n      });\n      slide.addText(r.pct, {\n        x: 5.6, y, w: 0.8, h: 0.45,\n        fontSize: 16, fontFace: \"Georgia\", bold: true,\n        color: r.c, align: \"left\", valign: \"middle\", margin: 0,\n      });\n      slide.addText(r.role, {\n        x: 6.4, y, w: 2.5, h: 0.45,\n        fontSize: 12, fontFace: \"Calibri\",\n        color: C.bodyText, align: \"left\", valign: \"middle\", margin: 0,\n      });\n    });\n\n    // Evaluation methods\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 5.3, y: 4.9, w: 4.2, h: 0.45,\n      fill: { color: C.white },\n      shadow: shadow(),\n    });\n    slide.addText(\"60% prefer build-and-buy  |  75% start with a free trial  |  73% ask other devs\", {\n      x: 5.4, y: 4.9, w: 4.0, h: 0.45,\n      fontSize: 10, fontFace: \"Calibri\",\n      color: C.bodyText, align: \"center\", valign: \"middle\", margin: 0,\n    });\n\n    slide.addText(\"Source: Stack Overflow 2024 Survey  |  n = 42,827\", {\n      x: 0.7, y: 5.2, w: 5, h: 0.25,\n      fontSize: 9, fontFace: \"Calibri\", italic: true,\n      color: C.subtleText, margin: 0,\n    });\n  }\n\n  // ─────────────────────────────────────────\n  // SLIDE 8: Key Takeaways\n  // ─────────────────────────────────────────\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.navy };\n\n    slide.addText(\"Takeaways: What These Trends Mean for Hiring & Retention\", {\n      x: 0.7, y: 0.35, w: 8.6, h: 0.7,\n      fontSize: 26, fontFace: \"Georgia\", bold: true,\n      color: C.white, align: \"left\", valign: \"middle\", margin: 0,\n    });\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.7, y: 1.1, w: 2.0, h: 0.05,\n      fill: { color: C.teal },\n    });\n\n    const takeaways = [\n      {\n        num: \"01\",\n        title: \"Plan for More Contractors\",\n        body: \"U.S. full-time employment fell 4 pp year-over-year. Freelancing and contracting remain significant at 16%+. Build flexible workforce strategies.\",\n        color: C.teal,\n      },\n      {\n        num: \"02\",\n        title: \"Hybrid Still Dominates, but In-Person Is Growing\",\n        body: \"In-person mandates rose to 20% (from 15% in 2022), but hybrid at 42% remains the norm. Offer flexibility to attract top talent.\",\n        color: C.tealLight,\n      },\n      {\n        num: \"03\",\n        title: \"DevRel and SRE Roles Command Premium Pay\",\n        body: \"Dev Advocates ($124K) and SREs ($99K) are among the highest-paid roles. Budget accordingly for these competitive markets.\",\n        color: C.accentOrange,\n      },\n      {\n        num: \"04\",\n        title: \"Language Choice Correlates with Pay\",\n        body: \"Niche functional languages (Erlang, Clojure, Elixir) pay >$93K median. Mainstream languages like JavaScript and PHP sit well below $65K.\",\n        color: C.accentGold,\n      },\n      {\n        num: \"05\",\n        title: \"Engage Developers Directly in Purchasing\",\n        body: \"62% of developers influence tech purchases. Vendor strategies should target individual contributors alongside management.\",\n        color: C.teal,\n      },\n    ];\n\n    takeaways.forEach((t, i) => {\n      const y = 1.35 + i * 0.82;\n      // Number circle\n      slide.addShape(pres.shapes.OVAL, {\n        x: 0.7, y: y + 0.05, w: 0.45, h: 0.45,\n        fill: { color: t.color },\n      });\n      slide.addText(t.num, {\n        x: 0.7, y: y + 0.05, w: 0.45, h: 0.45,\n        fontSize: 14, fontFace: \"Calibri\", bold: true,\n        color: C.white, align: \"center\", valign: \"middle\", margin: 0,\n      });\n      // Title\n      slide.addText(t.title, {\n        x: 1.35, y: y, w: 3.5, h: 0.35,\n        fontSize: 15, fontFace: \"Georgia\", bold: true,\n        color: C.white, align: \"left\", valign: \"middle\", margin: 0,\n      });\n      // Body\n      slide.addText(t.body, {\n        x: 1.35, y: y + 0.33, w: 8.0, h: 0.45,\n        fontSize: 11, fontFace: \"Calibri\",\n        color: C.midGray, align: \"left\", valign: \"top\", margin: 0,\n      });\n    });\n\n    slide.addText(\"Source: Stack Overflow Developer Survey 2024  |  survey.stackoverflow.co/2024\", {\n      x: 0.7, y: 5.2, w: 6, h: 0.25,\n      fontSize: 9, fontFace: \"Calibri\", italic: true,\n      color: C.subtleText, margin: 0,\n    });\n  }\n\n  // Write file\n  await pres.writeFile({ fileName: path.resolve(\"/app/output/final_deck.pptx\") });\n  console.log(\"Presentation saved to /app/output/final_deck.pptx\");\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 800, "startLine": 1, "totalLines": 800}}

