const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icon rendering
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Colors — Ocean Gradient with warm accents
const C = {
  navy: "0B1D3A",
  deepBlue: "0F2B52",
  teal: "1A7A8A",
  tealLight: "22A2B5",
  accentOrange: "E8873D",
  accentGold: "F5C342",
  white: "FFFFFF",
  offWhite: "F4F6F9",
  lightGray: "E2E8F0",
  midGray: "8896A6",
  darkText: "1B2A41",
  bodyText: "334155",
  subtleText: "64748B",
};

// Helpers
const shadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Analytics Team";
  pres.title = "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey";

  // Import icons
  const { FaBriefcase, FaBuilding, FaLaptopHouse, FaDollarSign, FaChartLine, FaCode, FaUsers, FaLightbulb, FaArrowRight, FaUserTie, FaGlobeAmericas, FaCheckCircle } = require("react-icons/fa");
  const { MdTrendingUp, MdWork, MdPeople } = require("react-icons/md");

  // Pre-render icons
  const iconBriefcase = await iconToBase64Png(FaBriefcase, "#FFFFFF", 256);
  const iconBuilding = await iconToBase64Png(FaBuilding, "#FFFFFF", 256);
  const iconLaptop = await iconToBase64Png(FaLaptopHouse, "#FFFFFF", 256);
  const iconDollar = await iconToBase64Png(FaDollarSign, "#FFFFFF", 256);
  const iconChart = await iconToBase64Png(FaChartLine, "#FFFFFF", 256);
  const iconCode = await iconToBase64Png(FaCode, "#FFFFFF", 256);
  const iconUsers = await iconToBase64Png(FaUsers, "#FFFFFF", 256);
  const iconBulb = await iconToBase64Png(FaLightbulb, "#FFFFFF", 256);
  const iconArrow = await iconToBase64Png(FaArrowRight, `#${C.accentOrange}`, 256);
  const iconCheck = await iconToBase64Png(FaCheckCircle, `#${C.teal}`, 256);
  const iconGlobe = await iconToBase64Png(FaGlobeAmericas, `#${C.tealLight}`, 256);

  // ─────────────────────────────────────────
  // SLIDE 1: Title Slide
  // ─────────────────────────────────────────
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };

    // Decorative top-right shape
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.0, y: 0, w: 3.0, h: 5.625,
      fill: { color: C.deepBlue },
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.3, y: 0, w: 0.06, h: 5.625,
      fill: { color: C.teal },
    });

    // Globe icon in right panel
    slide.addImage({ data: iconGlobe, x: 8.1, y: 1.5, w: 1.2, h: 1.2 });

    // Stats in right panel
    slide.addText("65,437", {
      x: 7.6, y: 2.9, w: 2.2, h: 0.6,
      fontSize: 28, fontFace: "Georgia", bold: true,
      color: C.accentGold, align: "center", margin: 0,
    });
    slide.addText("respondents", {
      x: 7.6, y: 3.4, w: 2.2, h: 0.35,
      fontSize: 13, fontFace: "Calibri",
      color: C.midGray, align: "center", margin: 0,
    });
    slide.addText("180+ countries", {
      x: 7.6, y: 3.8, w: 2.2, h: 0.35,
      fontSize: 13, fontFace: "Calibri",
      color: C.midGray, align: "center", margin: 0,
    });

    // Title block
    slide.addText("Developer Workforce &\nCompensation Trends", {
      x: 0.8, y: 1.1, w: 6.0, h: 1.8,
      fontSize: 36, fontFace: "Georgia", bold: true,
      color: C.white, align: "left", valign: "bottom",
      lineSpacingMultiple: 1.1, margin: 0,
    });

    // Teal accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: 3.05, w: 2.0, h: 0.06,
      fill: { color: C.teal },
    });

    slide.addText("2024 Stack Overflow Survey", {
      x: 0.8, y: 3.3, w: 6.0, h: 0.5,
      fontSize: 18, fontFace: "Calibri",
      color: C.tealLight, align: "left", margin: 0,
    });

    slide.addText("Key findings on employment patterns, salary benchmarks, and workforce\npreferences from the world's largest developer survey.", {
      x: 0.8, y: 4.0, w: 5.5, h: 0.7,
      fontSize: 12, fontFace: "Calibri",
      color: C.midGray, align: "left", margin: 0,
    });

    slide.addText("Source: survey.stackoverflow.co/2024", {
      x: 0.8, y: 5.1, w: 4, h: 0.3,
      fontSize: 10, fontFace: "Calibri", italic: true,
      color: C.subtleText, align: "left", margin: 0,
    });
  }

  // ─────────────────────────────────────────
  // SLIDE 2: Employment Status
  // ─────────────────────────────────────────
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    // Title area
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 1.1,
      fill: { color: C.navy },
    });
    slide.addText("84% of Developers Are Working, but Full-Time Employment Dips in the U.S.", {
      x: 0.7, y: 0.22, w: 8.6, h: 0.7,
      fontSize: 22, fontFace: "Georgia", bold: true,
      color: C.white, align: "left", valign: "middle", margin: 0,
    });

    // Big stat callouts — top row
    const stats = [
      { val: "69%", label: "Full-time\nEmployed", color: C.teal },
      { val: "16.4%", label: "Freelance /\nContract", color: C.tealLight },
      { val: "13.2%", label: "Full-time\nStudents", color: C.accentOrange },
    ];

    stats.forEach((s, i) => {
      const x = 0.7 + i * 3.0;
      slide.addShape(pres.shapes.RECTANGLE, {
        x, y: 1.45, w: 2.6, h: 1.55,
        fill: { color: C.white },
        shadow: shadow(),
      });
      slide.addShape(pres.shapes.RECTANGLE, {
        x, y: 1.45, w: 2.6, h: 0.07,
        fill: { color: s.color },
      });
      slide.addText(s.val, {
        x, y: 1.6, w: 2.6, h: 0.7,
        fontSize: 36, fontFace: "Georgia", bold: true,
        color: C.darkText, align: "center", margin: 0,
      });
      slide.addText(s.label, {
        x, y: 2.3, w: 2.6, h: 0.55,
        fontSize: 13, fontFace: "Calibri",
        color: C.bodyText, align: "center", margin: 0,
      });
    });

    // U.S. trend callout
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 3.35, w: 8.6, h: 1.5,
      fill: { color: C.white },
      shadow: shadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 3.35, w: 0.07, h: 1.5,
      fill: { color: C.accentOrange },
    });

    slide.addText("U.S. Full-Time Employment Trend", {
      x: 1.1, y: 3.5, w: 4, h: 0.35,
      fontSize: 15, fontFace: "Georgia", bold: true,
      color: C.darkText, align: "left", margin: 0,
    });

    slide.addText([
      { text: "69%", options: { fontSize: 28, fontFace: "Georgia", bold: true, color: C.teal } },
      { text: "  2023", options: { fontSize: 12, fontFace: "Calibri", color: C.subtleText } },
    ], { x: 1.1, y: 3.9, w: 2.5, h: 0.5, margin: 0 });

    slide.addImage({ data: iconArrow, x: 3.4, y: 4.0, w: 0.3, h: 0.3 });

    slide.addText([
      { text: "64.8%", options: { fontSize: 28, fontFace: "Georgia", bold: true, color: C.accentOrange } },
      { text: "  2024", options: { fontSize: 12, fontFace: "Calibri", color: C.subtleText } },
    ], { x: 3.9, y: 3.9, w: 2.5, h: 0.5, margin: 0 });

    slide.addText("4.2 percentage-point drop year-over-year", {
      x: 1.1, y: 4.4, w: 5, h: 0.3,
      fontSize: 11, fontFace: "Calibri", italic: true,
      color: C.subtleText, align: "left", margin: 0,
    });

    // Regional note
    slide.addText("U.K. & Ukraine: non-full-time respondents lean toward independent contracting.  Germany & India: lean toward full-time students.", {
      x: 5.5, y: 3.65, w: 3.5, h: 1.0,
      fontSize: 11, fontFace: "Calibri",
      color: C.bodyText, align: "left", valign: "middle", margin: 0,
    });

    slide.addText("Source: Stack Overflow 2024 Survey  |  n = 65,437", {
      x: 0.7, y: 5.2, w: 5, h: 0.25,
      fontSize: 9, fontFace: "Calibri", italic: true,
      color: C.subtleText, margin: 0,
    });
  }

  // ─────────────────────────────────────────
  // SLIDE 3: Work Environment Shift
  // ─────────────────────────────────────────
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 1.1,
      fill: { color: C.navy },
