// ─────────────────────────────────────────
// SLIDE 5: Experience vs. Salary Scatter
// ─────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.offWhite };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 1.1,
    fill: { color: C.navy },
  });
  slide.addText("Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries", {
    x: 0.7, y: 0.22, w: 8.6, h: 0.7,
    fontSize: 22, fontFace: "Georgia", bold: true,
    color: C.white, align: "left", valign: "middle", margin: 0,
  });

  // Scatter plot data
  const scatterData = [
    { name: "Senior Executive", values: [[17, 127388]] },
    { name: "Dev Advocate", values: [[16, 124203]] },
    { name: "Manager", values: [[15, 115999]] },
    { name: "Dev Experience", values: [[12, 109483]] },
    { name: "SRE", values: [[10, 99099]] },
    { name: "Cloud Infra.", values: [[13, 96666]] },
    { name: "Blockchain", values: [[9, 85925]] },
    { name: "Product Mgr", values: [[14, 80000]] },
    { name: "Full-stack", values: [[10, 63333]] },
    { name: "Front-end", values: [[8, 48787]] },
    { name: "Student", values: [[2, 15466]] },
  ];

  slide.addChart(pres.charts.SCATTER, scatterData, {
    x: 0.5, y: 1.2, w: 6.2, h: 4.0,
    chartColors: [C.teal, C.tealLight, C.deepBlue, C.accentOrange, "2E7D32", "7B1FA2", C.accentGold, "E91E63", "795548", "607D8B", "FF5722"],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisTitle: "Avg. Years of Experience",
    valAxisTitle: "Median Salary (USD)",
    catAxisLabelColor: C.subtleText, catAxisLabelFontSize: 9,
    valAxisLabelColor: C.subtleText, valAxisLabelFontSize: 9,
    catAxisTitleColor: C.bodyText, valAxisTitleColor: C.bodyText,
    catAxisMinVal: 0, catAxisMaxVal: 20,
    valAxisMinVal: 0, valAxisMaxVal: 140000,
    valGridLine: { color: C.lightGray, size: 0.5 },
    catGridLine: { color: C.lightGray, size: 0.5 },
    showLegend: true, legendPos: "r", legendFontSize: 8, legendColor: C.bodyText,
    lineSize: 0,
    valAxisNumFmt: "$#,##0",
  });

  // Callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.9, y: 3.6, w: 2.7, h: 1.5,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.9, y: 3.6, w: 0.07, h: 1.5,
    fill: { color: C.accentGold },
  });
  slide.addText("Outlier", {
    x: 7.2, y: 3.7, w: 2.2, h: 0.3,
    fontSize: 13, fontFace: "Georgia", bold: true,
    color: C.accentOrange, margin: 0,
  });
  slide.addText("Students earn $15,466 median with only ~2 years experience — the extreme lower-left point on the scatter plot.", {
    x: 7.2, y: 4.0, w: 2.2, h: 0.9,
    fontSize: 11, fontFace: "Calibri",
    color: C.bodyText, margin: 0,
  });

  slide.addText("Source: Stack Overflow 2024 Survey  |  n = 22,677 salary responses", {
    x: 0.7, y: 5.2, w: 7, h: 0.25,
    fontSize: 9, fontFace: "Calibri", italic: true,
    color: C.subtleText, margin: 0,
  });
}

